281	    /**
282	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
283	     * 64-character lower-case SHA-256 hex digest (see {@link org.springframework.samples.petclinic.util.Sha256})
284	     * of the normalized telephone, the lower-cased email (or an empty string when absent) and the
285	     * {@linkplain org.springframework.samples.petclinic.util.Soundex Soundex} code of the last name,
286	     * joined with {@code '|'}. Two owners are the same person only when their identity keys are
287	     * equal; because the telephone is part of the key, household members with different telephones
288	     * have different keys.
289	     */
290	    public String getIdentityKey() {
291	        String key = String.join("|",
292	            this.telephone == null ? "" : this.telephone,
293	            this.email == null ? "" : this.email.toLowerCase(Locale.ROOT),
294	            Soundex.encode(getLastName()));
295	        return Sha256.hex(key);
296	    }
297	
298	    /** Tenure, in elapsed fiscal years, at or beyond which an owner earns the tenure membership points. */
299	    private static final long TENURE_FISCAL_YEARS_FOR_POINTS = 1;
300	
301	    /** Household size at or above which an owner earns the household membership points. */
302	    private static final int HOUSEHOLD_SIZE_FOR_POINTS = 3;
303	
304	    /**
305	     * The owner's membership points, a score derived from the owner's own
306	     * fields. Starts at {@code 0}, gains {@code 2} when a contact email is on
307	     * file, gains {@code 1} when the owner has no namesakes, gains {@code 2}
308	     * when the owner belongs to a household of {@value #HOUSEHOLD_SIZE_FOR_POINTS}
309	     * or more, and gains {@code 3} when the owner's {@link #getTenureFiscalYears()
310	     * tenure} reaches {@value #TENURE_FISCAL_YEARS_FOR_POINTS} or more elapsed fiscal years.
311	     */
312	    public Integer getMembershipPoints() {
313	        int points = 0;
314	        boolean hasEmail = this.email != null && !this.email.isEmpty();
315	        if (hasEmail) {
316	            points += 2;
317	        }
318	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
319	        if (noNamesakes) {
320	            points += 1;
321	        }
322	        boolean largeHousehold = this.householdSize != null && this.householdSize >= HOUSEHOLD_SIZE_FOR_POINTS;
323	        if (largeHousehold) {
324	            points += 2;
325	        }
326	        Long tenureFiscalYears = getTenureFiscalYears();
327	        if (tenureFiscalYears != null && tenureFiscalYears >= TENURE_FISCAL_YEARS_FOR_POINTS) {
328	            points += 3;
329	        }
330	        return points;
331	    }
332	
333	    /**
334	     * The owner's membership level, a number from 1 to 4 mapped from the owner's
335	     * {@link #getMembershipPoints() membership points}: {@code 1} for 0-1 points,
336	     * {@code 2} for 2-3, {@code 3} for 4-5 and {@code 4} for 6 or more.
337	     *
338	     * <p>The level is held down to the {@linkplain #getMembershipLevelCap()
339	     * household ceiling} when one applies, so a new owner never outranks its
340	     * household by more than one level.
341	     */
342	    public Integer getMembershipLevel() {
343	        int level = pointsToLevel(getMembershipPoints());
344	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
345	            return this.membershipLevelCap;
346	        }
347	        return level;
348	    }
349	
350	    private static int pointsToLevel(int points) {
351	        if (points <= 1) {
352	            return 1;
353	        }
354	        if (points <= 3) {
355	            return 2;
356	        }
357	        if (points <= 5) {
358	            return 3;
359	        }
360	        return 4;
361	    }
362	
363	    /**
364	     * The ceiling applied to this owner's {@link #getMembershipLevel() membership
365	     * level}: one above the highest level among its household's existing members
366	     * when it was created, or {@code null} when no household member capped it.
367	     */
368	    public Integer getMembershipLevelCap() {
369	        return this.membershipLevelCap;
370	    }
371	
372	    public void setMembershipLevelCap(Integer membershipLevelCap) {
373	        this.membershipLevelCap = membershipLevelCap;
374	    }
375	
376	    /**
377	     * The owner's tenure: the number of whole fiscal years elapsed from the
378	     * {@link #registrationDate} to the server's current date — the count of 1 July
379	     * boundaries crossed between them (see {@link FiscalYear}), or {@code null} when no
380	     * registration date is on file. Zero while both dates fall in the same fiscal year,
381	     * and never negative for a registration date that is today or earlier.
382	     */
383	    public Long getTenureFiscalYears() {
384	        if (this.registrationDate == null) {
385	            return null;
386	        }
387	        return FiscalYear.elapsedYears(this.registrationDate, LocalDate.now());
388	    }
389	
390	    /**
391	     * The owner's marketing segment, formatted {@code '<TIER>_<AREA>'} (see
392	     * {@link OwnerSegment}). The {@code TIER} follows the {@linkplain
393	     * #getMembershipLevel() membership level} and the {@code AREA} follows the
394	     * {@linkplain #getLocality() locality}, so the segment is one of
395	     * {@code "PREMIUM_METRO"}, {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"}
396	     * or {@code "STANDARD_REGIONAL"}.
397	     */
398	    public String getOwnerSegment() {
399	        return OwnerSegment.of(getMembershipLevel(), getLocality());
400	    }
401	
402	    /**
403	     * The owner's preferred contact channel, derived from the fields on file:
404	     * {@code "EMAIL"} when a contact email is present, otherwise {@code "PHONE"}.
405	     */
406	    public String getContactPreference() {
407	        boolean hasEmail = this.email != null && !this.email.isEmpty();
408	        return hasEmail ? "EMAIL" : "PHONE";
409	    }
410	
411	    public Integer getNamesakeCount() {
412	        return this.namesakeCount;
413	    }
414	
415	    public void setNamesakeCount(Integer namesakeCount) {
416	        this.namesakeCount = namesakeCount;
417	    }
418	
419	    public Integer getHouseholdSize() {
420	        return this.householdSize;
421	    }
422	
423	    public void setHouseholdSize(Integer householdSize) {
424	        this.householdSize = householdSize;
425	    }
426	
427	    /**
428	     * Whether this owner, while not a declared household member, shares an existing owner's
429	     * last name and postcode but carries a different telephone. Determined once,
430	     * when the owner is created. A declared household member is never a suspected duplicate.
431	     */
432	    public Boolean getPossibleDuplicate() {
433	        return this.possibleDuplicate;
434	    }
435	
436	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
437	        this.possibleDuplicate = possibleDuplicate;
438	    }
439	
440	    /**
441	     * Whether this owner was knowingly created into a shared household. Such a declared member
442	     * bypasses the household-duplicate block and is not flagged as a suspected duplicate.
443	     */
444	    public boolean isDeclaredHouseholdMember() {
445	        return this.declaredHouseholdMember;
446	    }
447	
448	    public void setDeclaredHouseholdMember(boolean declaredHouseholdMember) {
449	        this.declaredHouseholdMember = declaredHouseholdMember;
450	    }
451	
452	    /**
453	     * The id of the existing owner this owner possibly duplicates, or {@code null}
454	     * when it has no such match.
455	     */
456	    public Integer getPossibleDuplicateOf() {
457	        return this.possibleDuplicateOf;
458	    }
459	
460	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
461	        this.possibleDuplicateOf = possibleDuplicateOf;
462	    }
463	
464	    /**
465	     * Whether this owner has been soft-deleted: {@code DELETE /api/owners/{id}} flags the owner
466	     * deleted and retains the row rather than removing it. A soft-deleted owner is still returned by
467	     * a read, but is ignored by the create endpoint's duplicate and identity checks. A newly created
468	     * owner is not deleted.
469	     */
470	    public boolean isDeleted() {
471	        return this.deleted;
472	    }
473	
474	    public void setDeleted(boolean deleted) {
475	        this.deleted = deleted;
476	    }
477	
478	    protected Set<Pet> getPetsInternal() {
479	        if (this.pets == null) {
480	            this.pets = new HashSet<>();
481	        }
482	        return this.pets;
483	    }
484	
485	    protected void setPetsInternal(Set<Pet> pets) {
486	        this.pets = pets;
487	    }
488	
489	    public List<Pet> getPets() {
490	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
491	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
492	        return Collections.unmodifiableList(sortedPets);
493	    }
494	
495	    public void setPets(List<Pet> pets) {
496	        this.pets = new HashSet<>(pets);
497	    }
498	
499	    public void addPet(Pet pet) {
500	        getPetsInternal().add(pet);
501	        pet.setOwner(this);
502	    }
503	
504	    /**
505	     * Return the Pet with the given name, or null if none found for this Owner.
506	     *
507	     * @param name to test
508	     * @return true if pet name is already in use
509	     */
510	    public Pet getPet(String name) {
511	        return getPet(name, false);
512	    }
513	
514	    /**
515	     * Return the Pet with the given name, or null if none found for this Owner.
516	     *
517	     * @param name to test
518	     * @return true if pet name is already in use
519	     */
520	    public Pet getPet(String name, boolean ignoreNew) {
521	        name = name.toLowerCase();
522	        for (Pet pet : getPetsInternal()) {
523	            if (!ignoreNew || !pet.isNew()) {
524	                String compName = pet.getName();
525	                compName = compName.toLowerCase();
526	                if (compName.equals(name)) {
527	                    return pet;
528	                }
529	            }
530	        }
531	        return null;
532	    }
533	
534	    public Pet getPet(Integer petId) {
535	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
536	    }
537	
538	    @Override
539	    public String toString() {
540	        return new ToStringCreator(this)
541	
542	            .append("id", this.getId())
543	            .append("new", this.isNew())
544	            .append("lastName", this.getLastName())
545	            .append("firstName", this.getFirstName())
546	            .append("address", this.address)
547	            .append("city", this.city)
548	            .append("telephone", this.telephone)
549	            .append("email", this.email)
550	            .toString();
551	    }
552	}
