17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Optional;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
41	import org.springframework.samples.petclinic.rest.validation.CityCapacityExceededException;
42	import org.springframework.samples.petclinic.rest.validation.DailyOwnerLimitExceededException;
43	import org.springframework.samples.petclinic.rest.validation.DisposableEmailException;
44	import org.springframework.samples.petclinic.rest.validation.DisposableEmailValidator;
45	import org.springframework.samples.petclinic.rest.validation.DuplicateIdentityException;
46	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
47	import org.springframework.samples.petclinic.rest.validation.FutureRegistrationDateException;
48	import org.springframework.samples.petclinic.rest.validation.InvalidPostcodeException;
49	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
50	import org.springframework.samples.petclinic.rest.validation.PostcodeValidator;
51	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
52	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
53	import org.springframework.samples.petclinic.service.ClinicService;
54	import org.springframework.samples.petclinic.service.IdempotencyKeyStore;
55	import org.springframework.samples.petclinic.service.OwnerAuditor;
56	import org.springframework.samples.petclinic.service.WelcomeNotifier;
57	import org.springframework.samples.petclinic.util.HouseholdIdGenerator;
58	import org.springframework.samples.petclinic.util.RegistrationDatePolicy;
59	import org.springframework.security.access.prepost.PreAuthorize;
60	import org.springframework.web.bind.annotation.CrossOrigin;
61	import org.springframework.web.bind.annotation.RequestMapping;
62	import org.springframework.web.bind.annotation.RestController;
63	import org.springframework.web.util.UriComponentsBuilder;
64	
65	import jakarta.transaction.Transactional;
66	
67	/**
68	 * @author Vitaliy Fedoriv
69	 */
70	
71	@RestController
72	@CrossOrigin(exposedHeaders = "errors, content-type")
73	@RequestMapping("/api")
74	public class OwnerRestControllerV1 implements OwnersApi {
75	
76	    /**
77	     * Maximum number of owners a single city may hold. A create request whose city already contains
78	     * this many owners is rejected as a conflict.
79	     */
80	    static final int MAX_OWNERS_PER_CITY = 50;
81	
82	    /**
83	     * Maximum number of owners that may be registered on a single day. A create request whose
84	     * registration date already holds this many owners is rejected with 429 Too Many Requests.
85	     */
86	    static final int MAX_OWNERS_PER_DAY = 100;
87	
88	    /**
89	     * Number of owners that may be registered on the current business day before a create/read
90	     * response flags {@code bulkSignupWarning}. Once more than this many owners exist for the day,
91	     * the warning is raised.
92	     */
93	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
94	
95	    /**
96	     * Number of owners a city may hold before a create/read response flags {@code capacityWarning}.
97	     * Once a city holds at least this many owners (but has not yet reached {@link
98	     * #MAX_OWNERS_PER_CITY}), the warning is raised to signal it is approaching the hard limit.
99	     */
100	    static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
101	
102	    private final ClinicService clinicService;
103	
104	    private final OwnerMapper ownerMapper;
105	
106	    private final PetMapper petMapper;
107	
108	    private final VisitMapper visitMapper;
109	
110	    private final OwnerAuditor ownerAuditor;
111	
112	    private final WelcomeNotifier welcomeNotifier;
113	
114	    private final IdempotencyKeyStore idempotencyKeyStore;
115	
116	    public OwnerRestControllerV1(ClinicService clinicService,
117	                                 OwnerMapper ownerMapper,
118	                                 PetMapper petMapper,
119	                                 VisitMapper visitMapper,
120	                                 OwnerAuditor ownerAuditor,
121	                                 WelcomeNotifier welcomeNotifier,
122	                                 IdempotencyKeyStore idempotencyKeyStore) {
123	        this.clinicService = clinicService;
124	        this.ownerMapper = ownerMapper;
125	        this.petMapper = petMapper;
126	        this.visitMapper = visitMapper;
127	        this.ownerAuditor = ownerAuditor;
128	        this.welcomeNotifier = welcomeNotifier;
129	        this.idempotencyKeyStore = idempotencyKeyStore;
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
135	        Collection<Owner> owners;
136	        if (lastName != null) {
137	            owners = this.clinicService.findOwnerByLastName(lastName);
138	        } else {
139	            owners = this.clinicService.findAllOwners();
140	        }
141	        if (owners.isEmpty()) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
150	        Owner owner = this.clinicService.findOwnerById(ownerId);
151	        if (owner == null) {
152	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
153	        }
154	        return new ResponseEntity<>(toOwnerDtoWithWarnings(owner), HttpStatus.OK);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
160	        if (idempotencyKey != null) {
161	            Optional<OwnerDto> existing = idempotencyKeyStore.findOwnerId(idempotencyKey)
162	                .map(this.clinicService::findOwnerById)
163	                .map(this::toOwnerDtoWithWarnings);
164	            if (existing.isPresent()) {
165	                return new ResponseEntity<>(existing.get(), HttpStatus.OK);
166	            }
167	        }
168	        resolveAddress(ownerFieldsDto);
169	        List<String> missingFields = OwnerFieldsValidator.findMissingFields(ownerFieldsDto);
170	        if (!missingFields.isEmpty()) {
171	            throw new MissingOwnerFieldsException(missingFields);
172	        }
173	        HttpHeaders headers = new HttpHeaders();
174	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
175	        if (!PostcodeValidator.isValidForCity(owner.getCity(), owner.getPostcode())) {
176	            throw new InvalidPostcodeException(owner.getPostcode(), owner.getCity());
177	        }
178	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
179	            throw new CityCapacityExceededException(owner.getCity());
180	        }
181	        if (RegistrationDatePolicy.isAfterServerDate(owner.getRegistrationDate())) {
182	            throw new FutureRegistrationDateException(owner.getRegistrationDate());
183	        }
184	        LocalDate registrationDate = RegistrationDatePolicy.effectiveDate(owner.getRegistrationDate());
185	        if (this.clinicService.countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
186	            throw new DailyOwnerLimitExceededException(registrationDate);
187	        }
188	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
189	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
190	        if (DisposableEmailValidator.isDisposable(owner.getEmail())) {
191	            throw new DisposableEmailException(owner.getEmail());
192	        }
193	        // The household is keyed on (last name, postcode): the id is deterministic, so owners with
194	        // the same last name and postcode share it automatically.
195	        owner.setHouseholdId(HouseholdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
196	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
197	        owner.setDeclaredHouseholdMember(declaredHouseholdMember);
198	        // An owner whose identity key matches an existing owner is the same person and is rejected,
199	        // unless it declares shared membership — in which case it is created as a known household
200	        // member. Household members with different telephones have distinct identity keys and are
201	        // not duplicates.
202	        if (!declaredHouseholdMember && this.clinicService.isIdentityDuplicate(owner)) {
203	            throw new DuplicateIdentityException(owner.getIdentityKey());
204	        }
205	        this.clinicService.saveOwner(owner);
206	        this.ownerAuditor.ownerCreated(owner);
207	        this.welcomeNotifier.welcome(owner);
208	        if (idempotencyKey != null) {
209	            this.idempotencyKeyStore.remember(idempotencyKey, owner.getId());
210	        }
211	        OwnerDto ownerDto = toOwnerDtoWithWarnings(owner);
212	        headers.setLocation(UriComponentsBuilder.newInstance()
213	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
214	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
215	    }
216	
217	    /**
218	     * Normalize the submitted address form and resolve the canonical stored {@code address}.
219	     * Whichever fields are supplied are normalized: the structured {@code addressLine1}/
220	     * {@code addressLine2} are kept (blank lines dropped to {@code null}), and {@code address}
221	     * is set to the composed structured address when {@code addressLine1} is present, otherwise
222	     * to the normalized flat {@code address}. Everything downstream reads the resolved
223	     * {@code address}, so it reflects the structured fields when present and the flat address
224	     * otherwise.
225	     */
226	    private void resolveAddress(OwnerFieldsDto ownerFieldsDto) {
227	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
228	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
229	        ownerFieldsDto.setAddressLine1(line1.isEmpty() ? null : line1);
230	        ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
231	        if (ownerFieldsDto.getAddressLine1() != null) {
232	            ownerFieldsDto.setAddress(
233	                AddressNormalizer.compose(ownerFieldsDto.getAddressLine1(), ownerFieldsDto.getAddressLine2()));
234	        } else {
235	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
236	        }
