238	
239	    /**
240	     * Map an owner to its DTO and stamp the advisory warning flags derived from the current state of
241	     * the clinic ({@code bulkSignupWarning} and {@code capacityWarning}).
242	     */
243	    private OwnerDto toOwnerDtoWithWarnings(Owner owner) {
244	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
245	        stampBulkSignupWarning(ownerDto);
246	        stampCapacityWarning(ownerDto, owner);
247	        return ownerDto;
248	    }
249	
250	    /**
251	     * Stamp {@code bulkSignupWarning}, which reflects whether more than {@link
252	     * #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been registered on the current business day.
253	     */
254	    private void stampBulkSignupWarning(OwnerDto ownerDto) {
255	        LocalDate today = RegistrationDatePolicy.effectiveDate(null);
256	        ownerDto.setBulkSignupWarning(
257	            this.clinicService.countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
258	    }
259	
260	    /**
261	     * Stamp {@code capacityWarning}, which reflects whether the owner's city already holds between
262	     * {@link #CITY_CAPACITY_WARNING_THRESHOLD} and {@link #MAX_OWNERS_PER_CITY} minus one owners,
263	     * signalling that it is approaching the per-city capacity limit.
264	     */
265	    private void stampCapacityWarning(OwnerDto ownerDto, Owner owner) {
266	        long cityOwners = this.clinicService.countOwnersByCity(owner.getCity());
267	        ownerDto.setCapacityWarning(
268	            cityOwners >= CITY_CAPACITY_WARNING_THRESHOLD && cityOwners < MAX_OWNERS_PER_CITY);
269	    }
